CREATE OR REPLACE FUNCTION public.tracking_finish(p_order uuid, p_run uuid, p_identity text, p_event jsonb, p_next timestamp with time zone, p_error text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare s public.shipment_tracking_state; o public.fulfillment_orders;
begin
 select * into s from public.shipment_tracking_state where order_id=p_order and lease_id=p_run and identity_key=p_identity and lease_until>now() for update;
 if not found then return false;end if;
 select * into o from public.fulfillment_orders where id=p_order and owner_id=s.owner_id for share;
 if not found or o.pii_purged_at is not null or private.shipment_tracking_identity(o)<>p_identity or o.label_cancelled_at is not null
 or private.shipment_tracking_terminal(s.provider,o.tracking_status_code) then return false;end if;
 if p_error is null and p_event is not null then
 insert into public.shipment_tracking_events(order_id,owner_id,account_id,identity_key,event_key,normalized_state,raw_code,raw_message,event_at,raw_event_time)
 values(p_order,s.owner_id,s.account_id,p_identity,md5(p_event::text),p_event->>'state',left(p_event->>'code',120),left(p_event->>'message',500),nullif(p_event->>'eventAt','')::timestamptz,left(p_event->>'eventTimeRaw',40)) on conflict do nothing;
 end if;
 update public.shipment_tracking_state set
 normalized_state=case when p_error is null then p_event->>'state' else normalized_state end,
 raw_code=case when p_error is null then left(p_event->>'code',120) else raw_code end,
 raw_message=case when p_error is null then left(p_event->>'message',500) else raw_message end,
 event_at=case when p_error is null then nullif(p_event->>'eventAt','')::timestamptz else event_at end,
 raw_event_time=case when p_error is null then left(p_event->>'eventTimeRaw',40) else raw_event_time end,
 observed_at=case when p_error is null then nullif(p_event->>'observedAt','')::timestamptz else observed_at end,
 movement_at=case when p_error is null then nullif(p_event->>'movementAt','')::timestamptz else movement_at end,
 last_checked_at=case when p_error is null then now() else last_checked_at end,
 next_poll_at=p_next,failures=case when p_error is null then 0 else failures+1 end,
 last_error=left(p_error,100),lease_id=null,lease_until=null where order_id=p_order;
 return true;
end;$function$

CREATE OR REPLACE FUNCTION public.tracking_webhook_wake(p_account uuid, p_owner uuid, p_tracking text, p_event_key text)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare n integer;
begin
 if p_event_key!~'^[a-f0-9]{64}$' or length(p_tracking)>100 then raise exception 'INVALID_TRACKING_EVENT';end if;
 if not exists(select 1 from public.shipment_tracking_settings where singleton and enabled) then return 0;end if;
 if not exists(select 1 from public.integration_accounts a join public.workspaces w on w.id=a.owner_id where a.id=p_account and a.owner_id=p_owner and a.provider='sendcloud' and a.enabled and a.status<>'disabled' and w.status in('active','trialing')) then return 0;end if;
 perform pg_advisory_xact_lock(hashtextextended('shipment-webhook:'||p_account::text,0));
 if (select count(*) from public.shipment_tracking_webhook_receipts where account_id=p_account and received_at>now()-interval '1 minute')>=120 then return 0;end if;
 insert into public.shipment_tracking_webhook_receipts(account_id,event_key) values(p_account,p_event_key) on conflict do nothing;
 if not found then return 0;end if;
 update public.shipment_tracking_state s set next_poll_at=least(s.next_poll_at,now()) from public.fulfillment_orders o
 where s.order_id=o.id and s.owner_id=p_owner and s.account_id=p_account and s.provider='sendcloud' and s.tracking_number=p_tracking
 and private.shipment_tracking_identity(o)=s.identity_key and o.label_cancelled_at is null
 and s.next_poll_at is not null and coalesce(s.normalized_state,'') not in('delivered','returned','cancelled')
 and upper(replace(coalesce(o.tracking_status_code,''),' ','_')) not in('DELIVERED','RETURNED','CANCELLED','CANCELED','DELIVERED_AT_ORIGIN','SHIPMENT_COLLECTED_BY_CUSTOMER');
 get diagnostics n=row_count;return n;
end;$function$

CREATE OR REPLACE FUNCTION private.shipment_tracking_purge_order()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if new.pii_purged_at is not null then
  delete from public.shipment_tracking_events where order_id=new.id;
  delete from public.shipment_tracking_state where order_id=new.id;
 end if;
 return new;
end;$function$

CREATE OR REPLACE FUNCTION private.orders_dashboard_projection_changed()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET lock_timeout TO '25ms'
AS $function$
DECLARE old_key text;new_key text;
BEGIN
 BEGIN
  IF NOT coalesce((SELECT maintenance_enabled FROM private.orders_projection_control WHERE singleton),false) THEN RETURN NULL;END IF;
  IF TG_OP='UPDATE' AND NEW IS NOT DISTINCT FROM OLD THEN RETURN NULL;END IF;
  IF TG_OP<>'INSERT' THEN
   old_key:=private.orders_dashboard_group_key(OLD.source_channel,OLD.order_number,OLD.id);
   INSERT INTO private.orders_projection_dirty(owner_id,group_key)
   VALUES(OLD.owner_id,old_key);
  END IF;
  IF TG_OP<>'DELETE' THEN
   new_key:=private.orders_dashboard_group_key(NEW.source_channel,NEW.order_number,NEW.id);
   IF TG_OP='INSERT' OR NEW.owner_id IS DISTINCT FROM OLD.owner_id OR new_key IS DISTINCT FROM old_key THEN
    INSERT INTO private.orders_projection_dirty(owner_id,group_key) VALUES(NEW.owner_id,new_key);
   END IF;
  END IF;
 EXCEPTION WHEN OTHERS THEN
  BEGIN
   PERFORM private.orders_projection_record_failure(SQLSTATE,
    CASE WHEN TG_OP='DELETE' THEN OLD.owner_id ELSE NEW.owner_id END,
    CASE WHEN TG_OP='DELETE' THEN private.orders_dashboard_group_key(OLD.source_channel,OLD.order_number,OLD.id)
    ELSE private.orders_dashboard_group_key(NEW.source_channel,NEW.order_number,NEW.id) END);
  EXCEPTION WHEN OTHERS THEN RAISE LOG 'orders projection queue and recorder unavailable';
  END;
 END;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION private.orders_dashboard_projection_reconcile(p_limit integer DEFAULT 100)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE g record;done integer:=0;
BEGIN
 IF p_limit IS NULL OR p_limit<1 OR p_limit>1000 THEN RAISE EXCEPTION 'INVALID_PROJECTION_BATCH_LIMIT';END IF;
 IF NOT coalesce((SELECT maintenance_enabled FROM private.orders_projection_control WHERE singleton),false) THEN RETURN 0;END IF;
 FOR g IN WITH oldest AS MATERIALIZED (
  SELECT id,owner_id,group_key FROM private.orders_projection_dirty ORDER BY id LIMIT p_limit*10
 ) SELECT owner_id,group_key,max(id) last_id FROM oldest
 GROUP BY owner_id,group_key ORDER BY min(id) LIMIT p_limit LOOP
  IF NOT pg_try_advisory_xact_lock(hashtextextended(g.owner_id::text||':'||g.group_key,719)) THEN CONTINUE;END IF;
  BEGIN
   PERFORM private.orders_dashboard_projection_refresh(g.owner_id,g.group_key);
   DELETE FROM private.orders_projection_dirty WHERE owner_id=g.owner_id AND group_key=g.group_key AND id<=g.last_id;
   done:=done+1;
  EXCEPTION WHEN OTHERS THEN
   PERFORM private.orders_projection_record_failure(SQLSTATE,g.owner_id,g.group_key);
  END;
 END LOOP;
 RETURN done;
END $function$

CREATE OR REPLACE FUNCTION private.orders_dashboard_projection_usable()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE own uuid:=private.app_workspace_owner_id();
BEGIN
 IF NOT coalesce((SELECT read_enabled AND maintenance_enabled FROM private.orders_projection_control WHERE singleton),false) THEN RETURN false;END IF;
 IF NOT private.app_has_permission('orders') OR NOT private.mfa_allowed() THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM private.orders_projection_dirty WHERE owner_id=own) THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM (SELECT id,owner_id,xmin,ctid FROM public.fulfillment_orders WHERE owner_id=own) o FULL JOIN
  (SELECT * FROM private.orders_projection_versions WHERE kind='orders' AND owner_id=own) v ON v.id=o.id
  WHERE (o.owner_id=own OR v.owner_id=own) AND
  (o.id IS NULL OR v.id IS NULL OR o.owner_id IS DISTINCT FROM v.owner_id OR (o.xmin::text||':'||o.ctid::text) IS DISTINCT FROM v.version)) THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM (SELECT projection_group_key FROM private.orders_dashboard_projection WHERE owner_id=own) p
  FULL JOIN (SELECT group_key FROM private.orders_projection_groups WHERE owner_id=own AND has_row) g
  ON g.group_key=p.projection_group_key WHERE p.projection_group_key IS NULL OR g.group_key IS NULL) THEN RETURN false;END IF;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION private.orders_dashboard_projection_cleanup(p_limit integer DEFAULT 100)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE n integer;g record;
BEGIN
 IF p_limit IS NULL OR p_limit<1 OR p_limit>1000 THEN RAISE EXCEPTION 'INVALID_PROJECTION_BATCH_LIMIT';END IF;
 n:=0;
 FOR g IN SELECT p.owner_id,p.projection_group_key FROM private.orders_dashboard_projection p
 WHERE NOT EXISTS(SELECT 1 FROM public.fulfillment_orders o WHERE o.owner_id=p.owner_id
  AND private.orders_dashboard_group_key(o.source_channel,o.order_number,o.id)=p.projection_group_key)
 OR EXISTS(SELECT 1 FROM private.orders_projection_versions v LEFT JOIN public.fulfillment_orders o ON o.id=v.id
  WHERE v.kind='orders' AND v.owner_id=p.owner_id AND v.group_key=p.projection_group_key
  AND (o.id IS NULL OR o.owner_id IS DISTINCT FROM v.owner_id OR
   private.orders_dashboard_group_key(o.source_channel,o.order_number,o.id) IS DISTINCT FROM v.group_key))
 OR EXISTS(SELECT 1 FROM public.fulfillment_orders o LEFT JOIN private.orders_projection_versions v ON v.kind='orders' AND v.id=o.id
  WHERE o.owner_id=p.owner_id AND private.orders_dashboard_group_key(o.source_channel,o.order_number,o.id)=p.projection_group_key
  AND o.pii_purged_at IS NOT NULL AND (v.id IS NULL OR v.version IS DISTINCT FROM (o.xmin::text||':'||o.ctid::text)))
 ORDER BY p.owner_id,p.projection_group_key LIMIT p_limit LOOP
  -- No source-write path takes this lock. A busy worker is retried next tick.
  IF NOT pg_try_advisory_xact_lock(hashtextextended(g.owner_id::text||':'||g.projection_group_key,719)) THEN CONTINUE;END IF;
  DELETE FROM private.orders_dashboard_projection WHERE owner_id=g.owner_id AND projection_group_key=g.projection_group_key;
  n:=n+1;
  BEGIN
   INSERT INTO private.orders_projection_dirty(owner_id,group_key) VALUES(g.owner_id,g.projection_group_key);
  EXCEPTION WHEN OTHERS THEN PERFORM private.orders_projection_record_failure(SQLSTATE,g.owner_id,g.projection_group_key);
  END;
 END LOOP;
 RETURN n;
END $function$
